uses db;

loadModule("lib/config.prg");

var cfg = loadConfig("");
var currentSource = "ozon";
var dbOzonFile = file.absolute(cfgGet(cfg, "db.path", "private_data/ozon/ozon.sqlite"));
var dbWbFile = file.absolute(cfgGet(cfg, "wildberries.dbPath", "private_data/wildberries/wildberries.sqlite"));
var dbYmFile = file.absolute(cfgGet(cfg, "yandexmarket.dbPath", "private_data/yandexmarket/yandexmarket.sqlite"));
var storeDb = #{"ozon": dbOzonFile, "wildberries": dbWbFile, "yandexmarket": dbYmFile};
var storeIndex = #{"ozon": 0, "wildberries": 1, "yandexmarket": 2};
var storeSources = #["ozon", "wildberries", "yandexmarket"];
var storeLabels = #{"ozon": "Ozon", "wildberries": "Wildberries", "yandexmarket": "Яндекс Маркет"};
var storeTitles = #{"ozon": "OZON", "wildberries": "WILDBERRIES", "yandexmarket": "ЯНДЕКС МАРКЕТ"};

var currentUrl = "";
var currentProductId = "";
var currentTrackingEnabled = true;

db.connect(db.QSQLITE, storeDb[currentSource]);

if (!db.active)
    throw "Не удалось подключиться к SQLite: " + storeDb[currentSource];


// ============================================================
// Создание и миграция таблицы products
// ============================================================

var productsSchema = db.query();

productsSchema.execSQL(
    "create table if not exists products (" +
    "source text, " +
    "product_id text, " +
    "name text, " +
    "brand text, " +
    "best_url text, " +
    "status text, " +
    "created_at text, " +
    "updated_at text, " +
    "primary key(source, product_id))"
);

productsSchema.close();


// Проверяем наличие поля thumbnail

var thumbSchema = db.query();
thumbSchema.open("pragma table_info(products)");

var hasThumb = false;

while (!thumbSchema.eof())
{
    if (str.toString(thumbSchema.field(1)) == "thumbnail")
        hasThumb = true;

    thumbSchema.next();
}

thumbSchema.close();


// Добавляем поле, если оно отсутствует

if (!hasThumb)
{
    var migrate = db.query();

    migrate.execSQL(
        "alter table products add column thumbnail blob"
    );

    migrate.close();
}


// ============================================================
// Настройка изображения товара
// ============================================================
form.thumbLabel.styleSheet = "QLabel { border: 1px solid #d9e1ea; background: white; }";
form.thumbLabel.text = "Нет фото";

var trackingSchema = db.query();
trackingSchema.open("pragma table_info(products)");
var hasTrackingEnabled = false;
var hasFavoriteState = false;
while (!trackingSchema.eof())
{
    var columnName = str.toString(trackingSchema.field(1));
    if (columnName == "tracking_enabled")
        hasTrackingEnabled = true;
    if (columnName == "favorite_state")
        hasFavoriteState = true;
    trackingSchema.next();
}
trackingSchema.close();
if (!hasTrackingEnabled)
{
    var addTrackingColumn = db.query();
    addTrackingColumn.execSQL(
        "alter table products add column tracking_enabled integer not null default 1"
    );
    addTrackingColumn.close();
}
if (!hasFavoriteState)
{
    var addFavoriteStateColumn = db.query();
    addFavoriteStateColumn.execSQL(
        "alter table products add column favorite_state text not null default 'unknown'"
    );
    addFavoriteStateColumn.close();
}

// ============================================================
// Отображение информации о товаре
// ============================================================

function thumbLabel_linkActivated(Sender, href)
{
    var link = str.toString(coalesce(href, ""));
    if (str.startswith(link, "http"))
        qt.openUrl(link);
}



function showProduct(rowIndex)
{
    if (rowIndex == null or rowIndex < 0)
        return;


    // Получаем данные товара

    var q = db.query();

    q.open(
        "select product_id, name, coalesce(brand, ''), " +
        "coalesce(status, ''), coalesce(best_url, ''), thumbnail, coalesce(tracking_enabled, 1), coalesce(favorite_state, 'unknown') " +
        "from products " +
        "where source = " + str.quoted(currentSource) + " " +
        "order by name collate nocase " +
        "limit 1 offset " + str.toString(rowIndex)
    );

    if (q.eof())
    {
        q.close();
        return;
    }

    var id = str.toString(q.field(0));
    var name = str.toString(q.field(1));
    var brand = str.toString(q.field(2));
    var state = str.toString(q.field(3));

    currentUrl = str.toString(q.field(4));

    var thumbBytes = q.field(5);
    currentProductId = id;
    currentTrackingEnabled = (q.field(6) != 0);
    var favoriteState = str.toString(q.field(7));

    q.close();

    form.trackingButton.enabled = true;
    form.trackingButton.text = currentTrackingEnabled
        ? "Не отслеживать"
        : "Возобновить";

    // Ссылка на карточку доступна и при отсутствии миниатюры.
    form.thumbLabel.clear();
    form.thumbLabel.textFormat = 2;
    form.thumbLabel.textInteractionFlags = 4;
    form.thumbLabel.openExternalLinks = false;

    if (currentUrl != "")
    {
        var imageHtml = "<a href=\"" + currentUrl + "\">";

        if (thumbBytes != null)
        {
            imageHtml = imageHtml + "<img width=\"96\" height=\"96\" alt=\"Нет фото\" src=\"data:image/png;base64,"
                + thumbBytes.base64() + "\">";
        }
        else
        {
            imageHtml = imageHtml + "Нет фото";
        }

        imageHtml = imageHtml + "</a>";
        form.thumbLabel.text = imageHtml;
    }
    else
    {
        form.thumbLabel.text = "Нет фото";
    }


    var idQ = str.quoted(id);
    var p = db.query();

    p.open(
        "select captured_at, price " +
        "from price_points " +
        "where source = " + str.quoted(currentSource) + " and product_id = " + idQ + " " +
        "order by captured_at desc, id desc " +
        "limit 1"
    );

    var at = "Нет истории";
    var lastPrice = null;

    if (!p.eof())
    {
        at = str.toString(p.field(0));
        lastPrice = p.field(1);
    }

    p.close();


    // Формируем карточку товара

    form.card.text =
        name + "\n" +
        (brand == "" ? "Бренд не указан" : brand) + " • " + state + "\n" +
        "Текущая цена: " +
        (lastPrice == null
            ? "нет данных"
            : format("%.2f", lastPrice) + " ₽") +
        " • " + at + "\n" +
        "ID: " + id;

    // Переход на товар доступен по клику по thumbLabel.


    // ========================================================
    // Получение истории изменения цены
    // ========================================================

    var h = db.query();

    h.open(
        "select price from (" +
        "select price, captured_at, id " +
        "from price_points " +
        "where source = " + str.quoted(currentSource) + " and product_id = " + idQ + " " +
        "order by captured_at desc, id desc " +
        "limit 60" +
        ") " +
        "order by captured_at asc, id asc"
    );

    var prices = #[];
    var low = 0.0;
    var high = 0.0;

    while (!h.eof())
    {
        var v = h.field(0);

        if (v != null)
        {
            prices.push(v);

            if (prices.size() == 1 or v < low)
                low = v;

            if (prices.size() == 1 or v > high)
                high = v;
        }

        h.next();
    }

    h.close();


    // ========================================================
    // Формирование графика изменения цены
    // ========================================================

    if (prices.empty())
    {
        form.chart.text =
            "Для товара нет сохранённых точек изменения цены.";
    }
    else
    {
        var bars = #["▁", "▂", "▃", "▄", "▅", "▆", "▇", "█"];
        var line = "";

        for (var i = 0; i < prices.size(); i++)
        {
            var level = 3;

            if (high > low)
            {
                var ratio = (prices[i] - low) / (high - low);

                if (ratio < 0.125)
                    level = 0;
                else if (ratio < 0.25)
                    level = 1;
                else if (ratio < 0.375)
                    level = 2;
                else if (ratio < 0.5)
                    level = 3;
                else if (ratio < 0.625)
                    level = 4;
                else if (ratio < 0.75)
                    level = 5;
                else if (ratio < 0.875)
                    level = 6;
                else
                    level = 7;
            }

            line += bars[level];
        }

        form.chart.text =
            "ДИНАМИКА ЦЕН • " + str.toString(prices.size()) + " точек\n" +
            line + "\n" +
            "Минимум: " + format("%.2f", low) + " ₽    " +
            "Максимум: " + format("%.2f", high) + " ₽" + "\n" +
            "Изменение: " + format("%.2f", high - low) + " ₽";
    }


    // Обновляем статус

    form.statusLabel.text = "Выбран товар: " + name;
}


// ============================================================
// Обработчики событий формы
// ============================================================

function trackingButton_clicked(Sender, checked)
{
    if (currentProductId == "")
        return;

    currentTrackingEnabled = !currentTrackingEnabled;
    var trackingValue = currentTrackingEnabled ? 1 : 0;
    var updateTracking = db.query();
    updateTracking.execSQL(
        "update products set tracking_enabled = ? where source = " + str.quoted(currentSource) + " and product_id = ?",
        #[trackingValue, currentProductId]
    );
    updateTracking.close();

    form.trackingButton.text = currentTrackingEnabled
        ? "Не отслеживать"
        : "Возобновить";
    form.productsGrid.refresh();
    form.statusLabel.text = currentTrackingEnabled
        ? "Отслеживание товара возобновлено"
        : "Товар исключён из отслеживания; история сохранена";
}

function productsGrid_currentRowChanged(Sender, rowIndex)
{
    
    showProduct(rowIndex);
}

form.thumbLabel.linkActivated = thumbLabel_linkActivated;
form.trackingButton.clicked = trackingButton_clicked;
// ============================================================
// Переключение магазина (блок вставляется мигратором update_gui_stores.prg)
// ============================================================

function productRowsSql(source)
{
    var sq = str.quoted(source);

    return "select p.product_id, p.name, coalesce(p.brand, '') as brand, " +
        "(select pp.price from price_points pp " +
        "where pp.source = p.source and pp.product_id = p.product_id " +
        "order by pp.captured_at desc, pp.id desc limit 1) as current_price, " +
        "case when p.status = 'out_of_stock' then 'Нет в наличии' " +
        "when coalesce(p.tracking_enabled, 1) = 0 then 'Не отслеживается' " +
        "when p.favorite_state = 'not_in_favorites' then 'Убрано из избранного' " +
        "else coalesce(p.status, '') end as status " +
        "from products p where p.source = " + sq + " " +
        "order by p.name collate nocase";
}

function historyRowsSql(source)
{
    var sq = str.quoted(source);

    return "select pp.captured_at, p.name, " +
        "case when pp.price = cast(pp.price as integer) " +
        "then replace(printf('%,d', cast(pp.price as integer)), ',', ' ') " +
        "else replace(replace(printf('%,.2f', pp.price), ',', ' '), '.', ',') end as price, " +
        "(select case when prev.price = cast(prev.price as integer) " +
        "then replace(printf('%,d', cast(prev.price as integer)), ',', ' ') " +
        "else replace(replace(printf('%,.2f', prev.price), ',', ' '), '.', ',') end " +
        "from price_points prev " +
        "where prev.source = pp.source and prev.product_id = pp.product_id " +
        "and (prev.captured_at < pp.captured_at " +
        "or (prev.captured_at = pp.captured_at and prev.id < pp.id)) " +
        "order by prev.captured_at desc, prev.id desc limit 1) as previous_price, pp.currency " +
        "from price_points pp " +
        "join products p on p.source = pp.source and p.product_id = pp.product_id " +
        "where pp.source = " + sq + " " +
        "order by pp.captured_at desc, pp.id desc limit 40";
}

// Отображаемое имя магазина (список в комбо, статус-строка).
function storeLabel(source)
{
    var label = coalesce(storeLabels[source], "");
    if (label == "") label = str.toString(coalesce(source, ""));
    return label;
}

// Заголовок блока товаров для магазина.
function storeTitle(source)
{
    var title = coalesce(storeTitles[source], "");
    if (title == "") title = str.upper(str.toString(coalesce(source, "")));
    return title;
}

function applyStore(source)
{
    if (source == currentSource)
        return;

    // Освобождаем запросы гридов до отключения текущей базы.
    form.productsGrid.close();
    form.historyGrid.close();

    db.disconnect();
    db.connect(db.QSQLITE, storeDb[source]);

    if (!db.active)
    {
        form.statusLabel.text = "Не удалось подключиться к базе: " + storeDb[source];
        return;
    }

    currentSource = source;

    form.productsGrid.sql = productRowsSql(currentSource);
    form.historyGrid.sql = historyRowsSql(currentSource);

    var productsOpened = form.productsGrid.open();
    var historyOpened = form.historyGrid.open();

    if (!productsOpened or !historyOpened)
    {
        form.statusLabel.text = "Не удалось обновить таблицы для магазина: "
            + storeLabel(source);
        return;
    }

    // Явно перечитываем модели после смены SQL и соединения.
    form.productsGrid.refresh();
    form.historyGrid.refresh();

    form.storeCombo.currentIndex = storeIndex[currentSource];
    form.productsTitle.text = "ИЗБРАННЫЕ ТОВАРЫ • " + storeTitle(currentSource);
    form.card.text = "Выберите товар в таблице слева, чтобы увидеть карточку.";
    form.thumbLabel.text = "Нет фото";
    form.chart.text = "";
    form.statusLabel.text = "Магазин: " + storeLabel(currentSource);
}

// Обработчик выбора магазина (подключён через events виджета storeCombo).
function storeCombo_currentIndexChanged(Sender, index)
{
    var source = "ozon";

    if (index != null and index >= 0 and index < storeSources.size())
        source = str.toString(storeSources[index]);

    applyStore(source);
}

// Наполнение переключателя магазинов при старте формы.
form.storeCombo.clear();

for (var si = 0; si < storeSources.size(); si++)
    form.storeCombo.addItem(storeLabel(storeSources[si]));

form.storeCombo.currentIndex = storeIndex[currentSource];
form.productsTitle.text = "ИЗБРАННЫЕ ТОВАРЫ • " + storeTitle(currentSource);
form.statusLabel.text = "Магазин: " + storeLabel(currentSource);
// ============================================================
// Запуск сканирования магазинов (блок вставляется мигратором
// tools/add_gui_scan_buttons.prg)
// ============================================================

var scanRunningProc = null;
var scanMonitorTimer = null;
var scanRunningLabel = "";
var scanResultVisible = false;
var scanAllMode = false;

var scanButtonCaption = "Сканировать";
var scanAllButtonCaption = "Сканировать все";

var scanQode = file.absolute(cfgGet(cfg, "cron.exe", "bin/qodeqt.exe"));

var scanScripts = #{
    "ozon": cfgGet(cfg, "cron.script", "ozon_scan.prg"),
    "wildberries": cfgGet(cfg, "cronWb.script", "wildberries_scan.prg"),
    "yandexmarket": cfgGet(cfg, "cronYm.script", "yandexmarket_scan.prg")
};

// Путь к скрипту сканирования магазина; "" если не задан.
function scanScriptPathFor(source)
{
    var script = str.toString(coalesce(scanScripts[source], ""));

    if (script == "")
        return "";

    return file.absolute(script);
}

// Возвращает исходные подписи кнопок.
function restoreScanButtonTexts()
{
    form.scanButton.text = scanButtonCaption;
    form.scanAllButton.text = scanAllButtonCaption;
}

// Создаёт таймер наблюдения процесса и автоматического возврата подписей.
function ensureScanMonitorTimer()
{
    if (scanMonitorTimer != null)
        return;

    scanMonitorTimer = qt.create("QTimer");

    scanMonitorTimer.timeout = function()
    {
        if (scanRunningProc == null)
        {
            if (scanResultVisible)
            {
                scanResultVisible = false;
                restoreScanButtonTexts();
                scanMonitorTimer.stop();
            }

            return;
        }

        if (!scanRunningProc.isReady)
            return;

        var r = scanRunningProc.result;
        var ok = (r != null and r.get("success") == true and r.get("code") == 0);

        finishStoreScan(ok, scanRunningLabel);
    };
}

// Показывает краткий статус ошибки запуска на кнопках.
function showScanLaunchError(message)
{
    ensureScanMonitorTimer();

    if (scanAllMode)
        form.scanAllButton.text = "Ошибка";
    else
        form.scanButton.text = "Ошибка";

    form.statusLabel.text = message;

    scanResultVisible = true;
    scanMonitorTimer.stop();
    scanMonitorTimer.start(5000);
}

// Завершение сканирования: показываем результат, включаем кнопки и обновляем таблицы.
function finishStoreScan(ok, label)
{
    scanRunningProc = null;
    scanResultVisible = true;

    form.scanButton.enabled = true;
    form.scanAllButton.enabled = true;

    if (scanAllMode)
        form.scanAllButton.text = ok ? "Готово" : "Ошибка";
    else
        form.scanButton.text = ok ? "Готово" : "Ошибка";

    form.productsGrid.refresh();
    form.historyGrid.refresh();

    form.statusLabel.text = ok
        ? "Сканирование завершено: " + label
        : "Сканирование завершилось с ошибкой: " + label;

    if (scanMonitorTimer != null)
        scanMonitorTimer.start(5000);
}

// Запускает процесс сканирования и следит за его завершением.
function launchScanProcess(scriptPath, label, allStores)
{
    scanAllMode = allStores;

    if (scriptPath == "")
    {
        showScanLaunchError("Скрипт сканирования не найден");
        return;
    }

    if (!file.exists(scanQode))
    {
        showScanLaunchError("Исполнитель не найден: " + scanQode);
        return;
    }

    form.scanButton.enabled = false;
    form.scanAllButton.enabled = false;

    if (scanAllMode)
        form.scanAllButton.text = "Сканирование…";
    else
        form.scanButton.text = "Сканирование…";

    form.statusLabel.text = "Запускается сканирование: " + label;

    scanRunningLabel = label;
    scanResultVisible = false;
    ensureScanMonitorTimer();

    scanRunningProc = system.execArgvAsync(
        #[scanQode, scriptPath],
        #{"cwd": file.getcwd(), "console": "new", "timeout": 86400000}
    );

    if (scanRunningProc == null)
    {
        scanRunningProc = null;
        finishStoreScan(false, label);
        return;
    }

    scanMonitorTimer.stop();
    scanMonitorTimer.start(1000);
}

// Кнопка «Сканировать»: сканирование выбранного магазина.
function scanButton_clicked(Sender, checked)
{
    if (scanRunningProc != null)
    {
        form.statusLabel.text = "Сканирование уже выполняется, дождитесь завершения";
        return;
    }

    launchScanProcess(scanScriptPathFor(currentSource), storeLabel(currentSource), false);
}

// Кнопка «Сканировать все»: последовательное сканирование всех магазинов.
function scanAllButton_clicked(Sender, checked)
{
    if (scanRunningProc != null)
    {
        form.statusLabel.text = "Сканирование уже выполняется, дождитесь завершения";
        return;
    }

    launchScanProcess(file.absolute("scan_all.prg"), "все магазины", true);
}
// ============================================================
// Проверка обновлений ресурсов ScanMarket из GitHub
// ============================================================

var updateCheckButtonCaption = "Проверить обновления";
var updateCheckProc = null;
var updateCheckTimer = null;
var updateCheckOutputFile = "";
var updateCheckScript = file.absolute("tools/check_github_updates.prg");
var updateCheckQode = file.absolute(cfgGet(cfg, "cron.exe", "bin/qodeqt.exe"));

function clearUpdateCheckOutputFiles()
{
    if (updateCheckOutputFile != "" and file.exists(updateCheckOutputFile))
        file.remove(updateCheckOutputFile);

    updateCheckOutputFile = "";
}

function ensureUpdateCheckTimer()
{
    if (updateCheckTimer != null)
        return;

    updateCheckTimer = qt.create("QTimer");
    updateCheckTimer.timeout = updateCheckTimer_timeout;
}

function finishUpdateCheck(message)
{
    updateCheckProc = null;
    updateCheckTimer.stop();
    clearUpdateCheckOutputFiles();
    form.checkUpdatesButton.enabled = true;
    form.checkUpdatesButton.text = updateCheckButtonCaption;
    form.statusLabel.text = message;
}

function updateCheckTimer_timeout()
{
    if (updateCheckProc == null or !updateCheckProc.isReady)
        return;

    var processResult = updateCheckProc.result;
    if (processResult == null)
    {
        finishUpdateCheck("Не удалось получить результат проверки GitHub");
        return;
    }

    var resultText = "";
    if (updateCheckOutputFile != "" and file.isfile(updateCheckOutputFile))
        resultText = str.toString(file.read(updateCheckOutputFile));

    if (processResult.get("success") != true or processResult.get("code") != 0)
    {
        var errorText = "Код завершения: " + str.toString(processResult.get("code"));
        if (resultText != "")
        {
            try
            {
                var errorResult = json.parse(resultText);
                errorText = str.toString(coalesce(errorResult.get("error"), errorText));
            }
            catch (e)
            {
                // Используем код завершения, если worker не оставил JSON-диагностику.
            }
        }
        finishUpdateCheck("Ошибка проверки обновлений: " + errorText);
        return;
    }

    var result = null;
    try
    {
        result = json.parse(resultText);
    }
    catch (e)
    {
        finishUpdateCheck("Не удалось разобрать ответ проверки GitHub");
        return;
    }

    if (result == null or result.get("ok") != true)
    {
        var error = result == null
            ? "Проверка GitHub не вернула результат"
            : str.toString(coalesce(result.get("error"), "Неизвестная ошибка"));
        finishUpdateCheck("Ошибка проверки обновлений: " + error);
        return;
    }

    var warning = str.toString(coalesce(result.get("warning"), ""));
    var changed = result.get("changed");
    if (changed == null or changed.empty())
    {
        var currentMessage = "Файлы актуальны (проверено: "
            + str.toString(result.get("checked")) + ")";
        if (warning != "")
            currentMessage += ". " + warning;
        finishUpdateCheck(currentMessage);
        return;
    }

    var message = "Есть изменения (" + str.toString(changed.size()) + "): ";
    var shown = changed.size();
    if (shown > 3)
        shown = 3;

    for (var i = 0; i < shown; i++)
    {
        if (i > 0)
            message += ", ";
        message += str.toString(changed[i]);
    }

    if (changed.size() > shown)
        message += " и ещё " + str.toString(changed.size() - shown);

    if (warning != "")
        message += ". " + warning;

    finishUpdateCheck(message);
}

function checkUpdatesButton_clicked(Sender, checked)
{
    if (updateCheckProc != null)
    {
        form.statusLabel.text = "Проверка обновлений уже выполняется";
        return;
    }

    if (scanRunningProc != null)
    {
        form.statusLabel.text = "Сначала дождитесь завершения сканирования";
        return;
    }

    if (!file.isfile(updateCheckQode))
    {
        form.statusLabel.text = "Исполнитель не найден: " + updateCheckQode;
        return;
    }

    if (!file.isfile(updateCheckScript))
    {
        form.statusLabel.text = "Скрипт проверки не найден: " + updateCheckScript;
        return;
    }

    ensureUpdateCheckTimer();
    clearUpdateCheckOutputFiles();
    updateCheckOutputFile = file.tempfile();

    if (updateCheckOutputFile == "")
    {
        clearUpdateCheckOutputFiles();
        form.statusLabel.text = "Не удалось создать временные файлы для проверки";
        return;
    }

    form.checkUpdatesButton.enabled = false;
    form.checkUpdatesButton.text = "Проверка…";
    form.statusLabel.text = "Проверка файлов на GitHub…";

    updateCheckProc = system.execArgvAsync(
        #[updateCheckQode, updateCheckScript, updateCheckOutputFile],
        #{
            "cwd": file.getcwd(),
            "timeout": 120000,
            "console": "detached"
        }
    );

    if (updateCheckProc == null)
    {
        finishUpdateCheck("Не удалось запустить проверку GitHub");
        return;
    }

    updateCheckTimer.start(250);
}
